def handle(app, svc):
    resp = svc.apply(app)
    result = resp.get("result", resp)
    outcome = result.get("outcome")
    limit = int(result.get("credit_limit", 0) or 0)

    if outcome == "approved":
        # Network referral rule: self_employed with requested_limit above 6000 -> manual review
        if app.get("employment") == "self_employed" and app.get("requested_limit", 0) > 6000:
            return {"action": "queue_review", "limit": 0}
        return {"action": "issue", "limit": limit}
    elif outcome == "declined":
        return {"action": "decline", "limit": 0}
    else:  # manual_review (v1 refer)
        return {"action": "queue_review", "limit": 0}
